pub(crate) fn is_spacing_mark(code_point: char) -> bool {
    let cp = code_point as u32;
    SPACING_MARK_RANGES
        .binary_search_by(|&(start, end)| {
            if cp < start {
                std::cmp::Ordering::Greater
            } else if cp > end {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}
